<?php $pageTitle='Support PACPET'; require 'config.php'; $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $s=$conn->prepare('INSERT INTO donations(donor_name,phone,email,amount,purpose,message) VALUES(?,?,?,?,?,?)'); $amount=(float)$_POST['amount']; $s->bind_param('sssdss',$_POST['donor_name'],$_POST['phone'],$_POST['email'],$amount,$_POST['purpose'],$_POST['message']); } include 'header.php'; ?><section class="page-head"><div class="container"><div class="eyebrow">SUPPORT</div><h1>Support PACPET's Educational Work</h1></div></section><section class="section"><div class="container split"><div><h2>Help strengthen learning opportunities.</h2><p>This page is a donation-interest form. Do not publish bank details, UPI IDs or payment gateway credentials until they are officially verified by PACPET.</p><div class="card"><h3>Possible support areas</h3><ul class="list"><li>Student learning resources</li><li>Books and educational materials</li><li>Residential programme support</li><li>Digital learning</li><li>Community events</li></ul></div></div><div class="form"><?php if($msg): ?><div class="flash"><?=e($msg)?></div><?php endif; ?><form method="post"><div class="form-grid"><div><label>Name *</label><input name="donor_name" required></div><div><label>Phone</label><input name="phone"></div><div><label>Email</label><input type="email" name="email"></div><div><label>Amount (INR)</label><input type="number" step="0.01" name="amount"></div><div class="full"><label>Purpose</label><input name="purpose"></div><div class="full"><label>Message</label><textarea name="message"></textarea></div></div><button class="btn">Submit Support Interest</button></form></div></div></section><?php include 'footer.php'; ?>
